Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='roadmappinscode', at=datetime(2026, 11, 15, 0, 0, 0), actor='assistant', title="Each project's tasks are a public roadmap repository of their own, which pins the code", body="A project's task list is the open list of one public store, kept in its own repository named after the project with the suffix roadmap; for this project it is fulfilium/suzatary-core-roadmap. The roadmap pins the application through a flake input, and the code names no roadmap, so another project can reuse the code without these tasks. Several roadmaps are combined in a deployment's view, never in one store. A deployment's own work, its failures, its data and its owner stay on its private upkeep chain, and the public list says nothing of them.", rationale="A submodule in either direction makes a cycle or puts the churn of task edits into the code's history.", supersedes=()))